(()=>{window.pdfjsLib={GlobalWorkerOptions:{},getDocument(options){return {promise:import('/assets/ocr/pdf.min.mjs').then(api=>{api.GlobalWorkerOptions.workerSrc='/assets/ocr/pdf.worker.min.mjs';return api.getDocument({...options,isEvalSupported:false,cMapUrl:location.origin+'/assets/ocr/pdf/cmaps/',cMapPacked:true,standardFontDataUrl:location.origin+'/assets/ocr/pdf/standard_fonts/',wasmUrl:location.origin+'/assets/ocr/pdf/wasm/'}).promise;})};}};})();
